arkiv.js:
// Faktisk Studio · Bevissikring — import og søk (lastes sist)
//
//  • Importer skjermbilder og skjermopptak (mobil/Mac) til saken: dra inn
//    eller «Velg filer…». Blir en egen sikring med sjekksummer og tidsstempel.
//  • «Gjør søkbar»: bygger indeks per sikring — sidens tekst, tekst lest i
//    bilder og video (Apple Vision) og tale (Studios transkribering).
//  • Søkefeltet søker i indeksen og viser treff med utdrag og tidskode.

(function () {
  const api = window.faktisk;
  const $ = id => document.getElementById(id);
  if (typeof api.bevisImport !== 'function') return;
  const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const MEDIA_RE = /\.(png|jpe?g|heic|heif|webp|gif|tiff?|bmp|mov|mp4|m4v|webm|mkv|avi|3gp|m4a|mp3|wav|aac|ogg|opus|flac)$/i;

  const el = {
    drop: $('impDrop'), pick: $('impPickBtn'), list: $('impList'), go: $('impBtn'), speech: $('impSpeech'),
    idxInfo: $('idxInfo'), idxBtn: $('idxBtn'), idxStop: $('idxStopBtn'), idxSpeech: $('idxSpeech'),
  };
  const A = { pending: [], running: false, stop: false, hits: {}, searchSeq: 0 };
  state.hits = {};

  const fmtT = t => { t = Math.max(0, Math.round(+t || 0)); return Math.floor(t / 60) + ':' + String(t % 60).padStart(2, '0'); };
  const SRC = { tekst: 'Tekst', ocr: 'Tekst i bilde', tale: 'Tale', meta: 'Info', info: 'Beskrivelse', kommentarer: 'Kommentarer' };

  // ------------------------------------------------------------
  //  Import
  // ------------------------------------------------------------
  function renderPending() {
    el.list.innerHTML = A.pending.map((p, i) => '<li><span title="' + esc(p) + '">' + esc(p.split('/').pop()) + '</span><button class="link-btn" data-i="' + i + '" type="button" title="Fjern">✕</button></li>').join('');
    el.go.hidden = !A.pending.length;
    el.go.textContent = 'Importer ' + A.pending.length + (A.pending.length === 1 ? ' fil' : ' filer');
  }
  function addPaths(paths) {
    const ok = paths.filter(p => MEDIA_RE.test(p));
    const skipped = paths.length - ok.length;
    for (const p of ok) if (!A.pending.includes(p)) A.pending.push(p);
    renderPending();
    if (skipped) setStatus(skipped + ' fil' + (skipped > 1 ? 'er' : '') + ' hoppet over — bare bilder, video og lyd kan importeres', 'warn');
  }
  el.list.addEventListener('click', e => { const b = e.target.closest('button[data-i]'); if (!b) return; A.pending.splice(+b.dataset.i, 1); renderPending(); });
  el.pick.addEventListener('click', async () => {
    const r = await api.openFileDialog({ title: 'Velg skjermbilder og opptak', properties: ['openFile', 'multiSelections'],
      filters: [{ name: 'Bilder, video og lyd', extensions: ['png', 'jpg', 'jpeg', 'heic', 'heif', 'webp', 'gif', 'mov', 'mp4', 'm4v', 'webm', 'mkv', 'm4a', 'mp3', 'wav'] }] });
    if (!r.canceled) addPaths(r.filePaths || [r.path]);
  });
  ['dragenter', 'dragover'].forEach(t => el.drop.addEventListener(t, e => { e.preventDefault(); el.drop.classList.add('is-over'); }));
  ['dragleave', 'drop'].forEach(t => el.drop.addEventListener(t, () => el.drop.classList.remove('is-over')));
  el.drop.addEventListener('drop', e => {
    e.preventDefault();
    const paths = Array.from(e.dataTransfer.files || []).map(f => { try { return api.bevisPathForFile ? api.bevisPathForFile(f) : f.path; } catch (err) { return ''; } }).filter(Boolean);
    if (!paths.length) { setStatus('Fikk ikke tak i filene — bruk «Velg filer…»', 'err'); return; }
    addPaths(paths);
  });
  // Unngå at filer som slippes utenfor feltet åpnes i vinduet
  window.addEventListener('dragover', e => e.preventDefault());
  window.addEventListener('drop', e => e.preventDefault());

  el.go.addEventListener('click', async () => {
    if (state.busy || A.running || !A.pending.length) return;
    if (window.bvRootReady && !window.bvRootReady()) return;
    const caseName = els.caseInput.value.trim();
    if (!caseName) { setStatus('Skriv inn en sak — sikringene samles per sak', 'err'); els.caseInput.focus(); return; }
    setBusy(true);
    setStatus('Importerer …');
    let r;
    try {
      r = await api.bevisImport({ root: state.root, caseName, paths: A.pending.slice(), url: els.urlInput.value.trim(), note: els.noteInput.value.trim(), pluginVersion: state.pluginVersion });
    } finally { setBusy(false); }
    if (!r.ok) { setStatus('Import feilet: ' + r.error, 'err'); return; }
    A.pending = []; renderPending();
    els.noteInput.value = '';
    state.highlight = r.dir;
    await refresh();
    setStatus('Importert' + (r.stamp && r.stamp.ok ? ' og tidsstemplet' : '') + '. Gjør innholdet søkbart …', 'ok');
    await indexDirs([r.dir], el.speech.checked);
  });

  // ------------------------------------------------------------
  //  Indeksering
  // ------------------------------------------------------------
  async function transcribe(dir, todo) {
    for (const t of todo) {
      if (A.stop) return;
      setStatus('Transkriberer tale i ' + t.rel.split('/').pop() + ' … (første gang lastes talemodellen ned)');
      const r = await api.transcribe({ inputPath: t.path, language: 'auto' });
      if (!r || !r.ok) { setStatus('Transkribering feilet: ' + ((r && r.error) || 'ukjent feil'), 'warn'); continue; }
      await api.bevisIndexSpeech({ dir, rel: t.rel, segments: r.segments || [], language: r.language || 'auto' });
    }
  }
  async function indexDirs(dirs, withSpeech) {
    if (A.running) return;
    A.running = true; A.stop = false;
    el.idxBtn.disabled = true; el.idxStop.hidden = false;
    let speechLeft = 0;
    try {
      for (let i = 0; i < dirs.length; i++) {
        if (A.stop) break;
        setStatus('Gjør søkbar ' + (i + 1) + ' av ' + dirs.length + ' …');
        const b = await api.bevisIndexBuild({ dir: dirs[i] });
        if (!b.ok) continue;
        if (withSpeech) await transcribe(dirs[i], b.speechTodo || []);
        else speechLeft += (b.speechTodo || []).length;
      }
      setStatus(A.stop ? 'Stoppet' : 'Ferdig — innholdet er søkbart' + (speechLeft ? ' (tale i ' + speechLeft + ' opptak er ikke transkribert)' : ''), 'ok');
    } finally {
      A.running = false;
      el.idxBtn.disabled = false; el.idxStop.hidden = true;
      updateIndexInfo();
      if (state.ui.q) runSearch();
    }
  }
  window.bvAutoIndex = dir => { if (!A.running) api.bevisIndexBuild({ dir }).then(updateIndexInfo).catch(() => {}); };

  async function updateIndexInfo() {
    if (!state.root) { el.idxInfo.textContent = ''; return; }
    const s = await api.bevisIndexStatus({ root: state.root, caseName: state.ui.caseFilter || undefined });
    if (!s.ok || !s.total) { el.idxInfo.textContent = ''; el.idxBtn.hidden = true; if (el.idxSpeech) el.idxSpeech.parentNode.hidden = true; return; }
    if (el.idxSpeech) el.idxSpeech.parentNode.hidden = false;
    const done = s.total - s.todo.length;
    el.idxInfo.textContent = done === s.total ? 'Alt er søkbart' : done + ' av ' + s.total + ' søkbare';
    el.idxBtn.hidden = false;
    el.idxBtn.dataset.todo = JSON.stringify(s.todo);
  }
  el.idxBtn.addEventListener('click', async () => {
    let todo = [];
    try { todo = JSON.parse(el.idxBtn.dataset.todo || '[]'); } catch (e) {}
    const withSpeech = !!(el.idxSpeech && el.idxSpeech.checked);
    if (!todo.length && !withSpeech) { setStatus('Alt er allerede søkbart'); return; }
    if (!todo.length) {
      // Alt indeksert, men tale kan mangle: bygg på nytt (raskt, gjenbruker OCR) for å finne opptak uten tale
      const st = await api.bevisList({ root: state.root });
      todo = (st.items || []).filter(it => !state.ui.caseFilter || it.case === state.ui.caseFilter).map(it => it.dir);
    }
    indexDirs(todo, withSpeech);
  });
  el.idxStop.addEventListener('click', () => { A.stop = true; setStatus('Stopper etter gjeldende fil …'); });

  // ------------------------------------------------------------
  //  Søk
  // ------------------------------------------------------------
  let searchTimer = null;
  async function runSearch() {
    const q = state.ui.q.trim();
    const seq = ++A.searchSeq;
    if (q.length < 2 || !state.root) { state.hits = {}; render(); return; }
    const r = await api.bevisSearch({ root: state.root, caseName: state.ui.caseFilter || undefined, q });
    if (seq !== A.searchSeq) return;
    state.hits = (r && r.hits) || {};
    render();
  }
  els.search.addEventListener('input', () => { clearTimeout(searchTimer); searchTimer = setTimeout(runSearch, 250); });
  els.caseFilter.addEventListener('change', () => { updateIndexInfo(); runSearch(); });

  window.bvHitsHtml = function (it) {
    const h = state.hits[it.dir];
    if (!h || !h.length || !state.ui.q) return '';
    const words = state.ui.q.toLowerCase().split(/\s+/).filter(w => w.length >= 2);
    const mark = s => { let out = esc(s); for (const w of words) out = out.replace(new RegExp('(' + w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/&/g, '&amp;') + ')', 'gi'), '<mark>$1</mark>'); return out; };
    return '<ul class="bv-hits">' + h.map(x => '<li><button class="bv-hit" type="button" data-act="hit" data-tab="' + esc(x.src === 'tale' ? 'tale' : x.src === 'ocr' ? 'ocr' : x.src === 'tekst' ? 'tekst' : 'fakta') + '">' +
      '<span class="bv-hit__src">' + esc(SRC[x.src] || x.src) + (x.t != null ? ' ' + fmtT(x.t) : '') + (x.file && x.src !== 'tekst' ? ' · ' + esc(x.file.split('/').pop()) : '') + '</span> ' + mark(x.snip) + '</button></li>').join('') + '</ul>';
  };
  window.bvHitMatch = it => !!(state.hits[it.dir]);

  if (api.onBevisLibraryChanged) api.onBevisLibraryChanged(() => updateIndexInfo());
  setTimeout(updateIndexInfo, 800);
})();

chrome-kobling.js:
// Faktisk Studio · Bevissikring — Chrome-utvidelsen (lastes etter main.js)
//
// Viser koble-koden utvidelsen trenger, holder Studio oppdatert på hvilket
// arkiv og hvilken sak nedlastinger fra Chrome skal havne i, og oppdaterer
// lista når en jobb fra Chrome blir ferdig.

(function () {
  const api = window.faktisk;
  const $ = id => document.getElementById(id);
  if (typeof api.bevisLinkStatus !== 'function') { const b = $('linkBlock'); if (b) b.hidden = true; return; }

  const el = { info: $('linkInfo'), token: $('linkToken'), copy: $('linkCopyBtn'), renew: $('linkNewBtn'), ext: $('linkExtBtn') };
  const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  let jobs = [];
  let sent = { root: null, caseName: null };

  function ago(iso) {
    if (!iso) return '';
    const s = Math.round((Date.now() - new Date(iso)) / 1000);
    return s < 60 ? 'nå nettopp' : s < 3600 ? Math.round(s / 60) + ' min siden' : new Date(iso).toLocaleString('nb-NO', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
  }

  async function render() {
    const st = await api.bevisLinkStatus();
    el.token.textContent = st.token;
    jobs = st.jobs || jobs;
    const active = jobs.filter(j => j.status === 'i kø' || j.status === 'kjører').length;
    const last = jobs[0];
    el.info.innerHTML =
      (st.running ? 'Klar for utvidelsen' + (st.lastSeen ? ' · sist i kontakt ' + esc(ago(st.lastSeen)) : '') : '<span class="bv-warnline">Ikke tilgjengelig: ' + esc(st.error || 'starter …') + '</span>') +
      (active ? '<br>Fra Chrome: ' + active + ' jobb' + (active > 1 ? 'er' : '') + ' pågår' : '') +
      (!active && last ? '<br>Siste fra Chrome: ' + esc((last.title || last.url).slice(0, 50)) + ' — ' + esc(last.status) + (last.error ? ' (' + esc(last.error.slice(0, 80)) + ')' : '') : '');
  }

  // Studio må vite arkiv og sak når utvidelsen sender noe uten å oppgi sak
  function syncConfig() {
    const root = state.root || '', caseName = els.caseInput.value.trim();
    if (root === sent.root && caseName === sent.caseName) return;
    sent = { root, caseName };
    api.bevisLinkConfig({ root, caseName }).catch(() => {});
  }
  setInterval(syncConfig, 2000);

  el.copy.addEventListener('click', async () => {
    await api.copyToClipboard(el.token.textContent);
    el.copy.textContent = 'Kopiert ✓';
    setTimeout(() => { el.copy.textContent = 'Kopier'; }, 1800);
  });
  el.renew.addEventListener('click', async () => {
    const ok = await window.faktiskDialog.confirm('Lage ny koble-kode? Utvidelsen må da få den nye koden før den virker igjen.', true);
    if (!ok) return;
    await api.bevisLinkNewToken();
    render();
  });
  el.ext.addEventListener('click', async () => {
    syncConfig();
    const r = await api.bevisLinkExtension();
    if (r.ok) setStatus('Utvidelsen ligger i Finder. I Chrome: chrome://extensions → Utviklermodus → «Last inn upakket» → velg mappa.', 'ok');
    else setStatus('Fant ikke utvidelsen: ' + r.error, 'err');
  });

  if (api.onBevisJobs) api.onBevisJobs(list => { jobs = list || []; render(); });
  if (api.onBevisLibraryChanged) api.onBevisLibraryChanged(() => { refresh(); });
  if (api.onBevisLinkChanged) api.onBevisLinkChanged(() => render());

  setTimeout(() => { syncConfig(); render(); }, 300);
  setInterval(render, 15000);
})();

chrome-utvidelse/background.js:
// Bakgrunn: høyreklikkmeny og «Sikre alt jeg ser».
importScripts('common.js', 'capture.js');

chrome.runtime.onInstalled.addListener(() => {
  chrome.contextMenus.removeAll(() => {
    chrome.contextMenus.create({ id: 'fs-all', title: 'Sikre alt jeg ser (Faktisk)', contexts: ['page'] });
    chrome.contextMenus.create({ id: 'fs-video', title: 'Last ned video i Faktisk Studio', contexts: ['page', 'link', 'video'] });
  });
  fsGet('token').then(({ token }) => { if (!token) chrome.runtime.openOptionsPage(); });
});

async function badge(text, color) {
  await chrome.action.setBadgeBackgroundColor({ color });
  await chrome.action.setBadgeText({ text });
  if (text && text !== '…') setTimeout(() => chrome.action.setBadgeText({ text: '' }), 5000);
}
async function remember(msg, ok) {
  await chrome.storage.local.set({ lastMessage: { msg, ok, at: Date.now() } });
}
async function progress(msg, pct, done, ok) {
  await chrome.storage.session.set({ progress: { msg, pct: pct || 0, done: !!done, ok: ok !== false, at: Date.now() } });
}

// Én sikring av gangen
let running = false;

async function studioReady() {
  try {
    const st = await fsCall('/status');
    if (!(st.features || []).includes('full')) return { ok: false, reason: 'old', st };
    if (st.rootProblem) return { ok: false, reason: 'root', st };
    return { ok: true, st };
  } catch (e) { return { ok: false, reason: e.noToken ? 'token' : 'offline', error: e.message }; }
}

async function captureAll(tab, opts) {
  if (running) throw new Error('En sikring pågår allerede');
  if (!tab || !/^https?:/i.test(tab.url || '')) throw new Error('Kan bare sikre vanlige nettsider');
  running = true;
  await badge('…', '#0050FC');
  try {
    const report = (msg, pct) => progress(msg, pct);
    await progress('Starter …', 1);
    const studio = await studioReady();
    const cap = await fsCaptureAll(tab, opts, report);
    let msg;
    if (studio.ok) {
      const r = await fsDeliverToStudio(tab, cap, opts, report);
      msg = 'Sendt til Faktisk Studio (' + cap.files.length + ' filer' + (opts.video ? ', video lastes ned i Studio' : '') + ').';
      void r;
    } else {
      const r = await fsSaveLocally(tab, cap, opts, report);
      const why = studio.reason === 'old' ? 'Studio er for gammel for «Sikre alt»' : studio.reason === 'root' ? (studio.st.rootProblem || 'Studio mangler arkivmappe') : 'Studio kjører ikke';
      msg = why + ' — lagret i Nedlastinger/' + r.folder + (r.stamp && r.stamp.ok ? ' (tidsstemplet)' : '') + '.';
    }
    if (cap.warnings.length) msg += ' Merknader: ' + cap.warnings.join(' ');
    await progress(msg, 100, true, true);
    await remember(msg, true);
    await badge('✓', '#1E9E5A');
    return { ok: true, msg };
  } catch (err) {
    await progress(err.message, 100, true, false);
    await remember(err.message, false);
    await badge('!', '#D9534F');
    return { ok: false, error: err.message };
  } finally { running = false; }
}

async function optionsFromStorage() {
  const o = await fsGet(['optScroll', 'optExpand', 'optImages', 'optVideo', 'caseName']);
  return { scroll: o.optScroll !== false, expand: o.optExpand !== false, images: o.optImages !== false, video: o.optVideo !== false, caseName: o.caseName || '', note: '' };
}

chrome.runtime.onMessage.addListener((m, sender, reply) => {
  if (!m || m.target === 'offscreen') return;
  if (m.type === 'captureAll') {
    chrome.tabs.get(m.tabId).then(tab => captureAll(tab, m.opts)).then(reply);
    return true;
  }
  if (m.type === 'isRunning') { reply({ running }); return; }
});

chrome.contextMenus.onClicked.addListener(async (info, tab) => {
  const caseName = await fsCaseName();
  try {
    if (info.menuItemId === 'fs-all') {
      await captureAll(tab, await optionsFromStorage());
    } else if (info.menuItemId === 'fs-video') {
      const url = fsVideoUrl(info, tab);
      if (!url) throw new Error('Fant ingen adresse å laste ned fra');
      try {
        await fsCall('/download', { url, case: caseName, extVersion: FS_EXT_VERSION });
      } catch (err) {
        if (!err.offline) throw err;
        await chrome.tabs.create({ url: 'faktisk-studio://last-ned?url=' + encodeURIComponent(url) });
        await remember('Studio kjørte ikke — åpner appen, som spør før nedlasting.', true);
        return;
      }
      await remember('Sendt til Studio: ' + url, true);
      await badge('↓', '#0050FC');
    }
  } catch (err) {
    await remember(err.message, false);
    await badge('!', '#D9534F');
    if (err.noToken || err.status === 401) chrome.runtime.openOptionsPage();
  }
});

chrome-utvidelse/capture.js:
// «Sikre alt jeg ser» — kjøres i bakgrunnen (service worker).
//
// 1. Åpner flere kommentarer/svar (valgfritt, maks noen runder)
// 2. Ruller gjennom siden fra toppen og tar et skjermbilde per skjermhøyde
//    (finner selv boksen som ruller — Facebook og X ruller ofte en indre boks)
// 3. Samler teksten fra hvert steg (feeds fjerner innlegg øverst underveis)
// 4. Nettarkiv (MHTML), HTML, metadata, bilder på siden, video
// 5. Leverer til Studio (eller en annen lokal motor) — eller, uten Studio,
//    lagrer i Nedlastinger/Bevissikring med manifest, sjekksummer og tidsstempel.

const FS_MAX_SHOTS = 40;
const FS_SHOT_GAP_MS = 650;     // Chrome tillater maks 2 skjermbilder i sekundet
const FS_MAX_IMAGES = 60;
const FS_MAX_IMAGE_BYTES = 25 * 1024 * 1024;

// ------------------------------------------------------------
//  Funksjoner som kjøres i siden (må være selvstendige)
// ------------------------------------------------------------
function fsPageScroller(cmd, arg) {
  if (!window.__fsScroller) {
    const pick = () => {
      const se = document.scrollingElement || document.documentElement;
      if (se.scrollHeight > se.clientHeight + 40) return se;
      let best = null, bestArea = 0;
      for (const el of document.querySelectorAll('body *')) {
        const cs = getComputedStyle(el);
        if (!/(auto|scroll)/.test(cs.overflowY)) continue;
        if (el.scrollHeight <= el.clientHeight + 40) continue;
        const r = el.getBoundingClientRect();
        const area = Math.max(0, Math.min(r.width, innerWidth)) * Math.max(0, Math.min(r.height, innerHeight));
        if (area > bestArea) { best = el; bestArea = area; }
      }
      return best || se;
    };
    window.__fsScroller = {
      el: null, origin: 0,
      start() { this.el = pick(); this.origin = this.el.scrollTop; return this.info(); },
      info() { const e = this.el; return { top: e.scrollTop, height: e.scrollHeight, view: e.clientHeight, inner: e !== (document.scrollingElement || document.documentElement) }; },
      to(y) { this.el.scrollTop = y; return this.info(); },
      step() { const e = this.el; const b = e.scrollTop; e.scrollTop = b + Math.round(e.clientHeight * 0.85); const i = this.info(); i.moved = e.scrollTop !== b; return i; },
      back() { this.el.scrollTop = this.origin || 0; return this.info(); },
    };
  }
  const s = window.__fsScroller;
  if (cmd === 'start') return s.start();
  if (cmd === 'to') return s.to(arg || 0);
  if (cmd === 'step') return s.step();
  if (cmd === 'back') { const r = s.back(); delete window.__fsScroller; return r; }
  if (cmd === 'text') return document.body ? document.body.innerText : '';
  return null;
}

function fsPageExpand(rounds) {
  const re = /^(se flere kommentarer|vis flere kommentarer|se tidligere kommentarer|vis tidligere kommentarer|view more comments|view previous comments|see more comments|more comments|se alle \d+ svar|vis alle \d+ svar|se \d+ svar|vis \d+ svar|view all \d+ repl(y|ies)|view \d+ repl(y|ies)|\d+ (svar|replies)|see more|se mer|vis mer|show more|more replies|flere svar|load more comments)$/i;
  return (async () => {
    let clicked = 0;
    for (let r = 0; r < rounds; r++) {
      const btns = Array.from(document.querySelectorAll('[role="button"], button, span[dir="auto"]')).filter(b => {
        const t = (b.innerText || '').replace(/\s+/g, ' ').trim();
        if (!t || t.length > 40 || !re.test(t)) return false;
        const a = b.closest('a[href]');
        if (a && !/^javascript:|#$/.test(a.getAttribute('href') || '')) return false;   // aldri lenker til andre sider
        const rc = b.getBoundingClientRect();
        return rc.width > 0 && rc.height > 0;
      });
      if (!btns.length) break;
      for (const b of btns.slice(0, 40)) { try { b.click(); clicked++; } catch (e) {} }
      await new Promise(res => setTimeout(res, 1300));
    }
    return clicked;
  })();
}

function fsPageCollect() {
  const meta = {};
  for (const m of Array.from(document.querySelectorAll('meta[property], meta[name], meta[itemprop]')).slice(0, 300)) {
    const k = m.getAttribute('property') || m.getAttribute('name') || m.getAttribute('itemprop');
    const v = m.getAttribute('content');
    if (k && v && v.length < 2000 && !(k in meta)) meta[k] = v;
  }
  const seen = new Set(), images = [];
  const add = (u, w, h, kind) => {
    if (!u || seen.has(u) || !/^(https?:|data:image\/)/.test(u)) return;
    seen.add(u); images.push({ url: u, w: w || 0, h: h || 0, kind });
  };
  for (const img of document.images) {
    const w = img.naturalWidth, h = img.naturalHeight;
    if (w >= 200 && h >= 200) add(img.currentSrc || img.src, w, h, 'img');
  }
  const videos = [];
  for (const v of document.querySelectorAll('video')) {
    if (v.poster) add(v.poster, 0, 0, 'poster');
    const src = v.currentSrc || v.src || (v.querySelector('source') || {}).src || '';
    videos.push({ src, blob: /^blob:/.test(src), direct: /^https?:/.test(src), w: v.videoWidth, h: v.videoHeight, duration: isFinite(v.duration) ? v.duration : null });
  }
