// ============================================================
//  Oppstart
// ============================================================
(async function init() {
  // Vent til alle skriptene (stikkprove, profil, sikkerhet …) er lastet —
  // ellers kan svar fra Studio komme før de har registrert seg
  if (document.readyState === 'loading') await new Promise(r => document.addEventListener('DOMContentLoaded', r, { once: true }));
  try {
    const [appV, plugins] = await Promise.all([api.appVersion(), api.pluginStatus()]);
    const me = (plugins || []).find(p => p.id === PLUGIN_ID);
    state.pluginVersion = me ? me.version : '';
    $('appVersion').textContent = me ? 'v' + appV + ' · plugin v' + me.version : 'v' + appV;
  } catch (e) {}

  if (!hasApi) {
    setStatus('Denne pluginen krever en nyere Faktisk Studio. Oppdater appen fra Malsiden.', 'err');
    els.captureBtn.disabled = els.regionBtn.disabled = els.openBtn.disabled = true;
    return;
  }

  api.onBevisProgress(p => { if (state.busy && p && p.msg) setStatus(p.msg); });
  api.onBevisWindow(renderWindow);

  let saved = null;
  try { const res = await api.stateLoad(PLUGIN_ID); saved = res && res.ok && res.state; } catch (e) {}
  if (saved) {
    state.root = saved.root || '';
    els.caseInput.value = saved.caseName || '';
    els.urlInput.value = saved.url || '';
    if (saved.options) optBoxes.forEach(b => { if (b.dataset.opt in saved.options) b.checked = !!saved.options[b.dataset.opt]; });
    if (saved.ui) state.ui = Object.assign(state.ui, saved.ui);
  }
  // Ingen stille standardmappe — sikkerhet.js ber brukeren velge
  if (window.bvSecurityInit) { try { await window.bvSecurityInit(); } catch (e) { console.error('bvSecurityInit', e); } }
  els.waybackHint.hidden = !document.querySelector('[data-opt="wayback"]').checked;
  document.querySelector('[data-opt="comments"]').disabled = !document.querySelector('[data-opt="media"]').checked;
  els.search.value = state.ui.q || '';
  if (window.bvProfileApply) window.bvProfileApply(saved && saved.profile);
  if (window.bvSampleApply) window.bvSampleApply(saved && saved.sample);
  renderRoot();
  renderWindow(await api.bevisWindowState());
  refreshTools();
  await refresh();
})();

profil.js:
// Faktisk Studio · Bevissikring — profiler og innlegg (lastes etter stikkprove.js)
//
// 1) Åpne profilen i sikringsvinduet og logg inn.
// 2) «Sikre profilinfo»: toppen av profilen + Om-siden (+ sidegjennomsiktighet).
// 3) «Finn innlegg»: ruller og samler lenker til innleggene. Lista lagres og
//    hashes i saken før noe sikres.
// 4) Huk av og «Sikre valgte»: hvert innlegg åpnes, kommentarene åpnes, og
//    innlegget sikres som egen sikring. Fremdriften logges, så jobben kan
//    fortsettes senere.

(function () {
  const $ = id => document.getElementById(id);
  const api = window.faktisk;
  if (typeof api.bevisProfileScan !== 'function') return;

  const el = {
    url: $('pUrl'), open: $('pOpenBtn'), info: $('pInfoBtn'), max: $('pMax'), until: $('pUntil'), expand: $('pExpand'),
    scan: $('pScanBtn'), stop: $('pStopBtn'), lists: $('pListSelect'), box: $('pResBox'), meta: $('pMeta'),
    all: $('pAllBtn'), none: $('pNoneBtn'), sel: $('pSel'), list: $('pList'), comments: $('pExpandComments'),
    run: $('pRunBtn'), runStop: $('pRunStop'), reveal: $('pRevealBtn'),
  };
  const P = { current: null, lists: [], selected: new Set(), running: false, stop: false, scanning: false };
  const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const fmtD = s => { const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})$/); return m ? (m[3] + '.' + m[2] + '.' + m[1].slice(2)) : ''; };

  function caseOk() {
    const c = els.caseInput.value.trim();
    if (!c) { setStatus('Skriv inn en sak først', 'err'); els.caseInput.focus(); return ''; }
    return c;
  }
  function busy(b) {
    el.open.disabled = el.info.disabled = el.scan.disabled = b;
    el.stop.disabled = !P.scanning;
    renderRun();
  }

  // ------------------------------------------------------------
  //  Åpne og profilinfo
  // ------------------------------------------------------------
  el.open.addEventListener('click', async () => {
    const url = el.url.value.trim();
    if (!url) { setStatus('Lim inn lenken til profilen eller siden', 'err'); el.url.focus(); return; }
    const r = await api.bevisOpen({ url });
    if (r.cancelled) setStatus('Avbrutt');
    else if (!r.ok || !r.url) setStatus('Ugyldig adresse', 'err'); else { setStatus('Logg inn i vinduet om nødvendig.'); scheduleSaveState(); }
  });

  async function captureUrl(url, tag, maxScroll, expandComments) {
    if (window.bvRootReady && !window.bvRootReady()) return { status: 'feil', error: 'ingen arkivmappe', login: true };
    const open = await api.bevisOpen({ url, wait: true, settleMs: 3000 });
    if (!open.ok) return { status: 'feil', error: 'kunne ikke åpne siden', finalUrl: '' };
    if (/\/(login|checkpoint|i\/flow\/login|accounts\/login)/.test(open.finalUrl || '')) return { status: 'feil', error: 'krever innlogging', login: true };
    if (expandComments) { try { await api.bevisExpand({ rounds: 6, comments: true }); } catch (e) {} }
    const r = await api.bevisCapture({
      root: state.root, caseName: els.caseInput.value.trim(), note: els.noteInput.value.trim(), url,
      pluginVersion: state.pluginVersion, options: options(), tag, maxScroll,
    });
    if (!r.ok) return { status: 'feil', error: r.error };
    return { status: 'ok', dir: r.dir, fingerprint: r.fingerprint, finalUrl: open.finalUrl };
  }

  el.info.addEventListener('click', async () => {
    if (state.busy || P.running) return;
    if (!caseOk()) return;
    const urls = await api.bevisProfileUrls({ url: el.url.value.trim() || ((await api.bevisWindowState()).url || '') });
    if (!urls.ok) { setStatus('Lim inn lenken til profilen', 'err'); return; }
    setBusy(true); busy(true);
    const done = [];
    try {
      setStatus('Sikrer toppen av profilen …');
      const top = await captureUrl(urls.profile, { kind: 'profil', part: 'topp', suffix: 'profil', account: urls.profile }, 3, false);
      if (top.login) { setStatus('Siden krever innlogging. Logg inn i vinduet og prøv igjen.', 'err'); return; }
      done.push(top.status === 'ok' ? 'profil' : 'profil (feilet)');
      for (const a of urls.about) {
        setStatus('Sikrer «' + a.part + '» …');
        if (a.optional) {
          const probe = await api.bevisOpen({ url: a.url, wait: true, settleMs: 2500 });
          if (!probe.ok || !/transparency/i.test(probe.finalUrl || '')) continue;   // finnes bare for sider
          const t = ((await api.bevisWindowState()).title || '').trim();
          if (!t || /^facebook$|ikke tilgjengelig|not available|not found|fant ikke/i.test(t)) continue;
        }
        const r = await captureUrl(a.url, { kind: 'profil', part: a.part, suffix: a.part, account: urls.profile }, 6, false);
        done.push(r.status === 'ok' ? a.part : a.part + ' (feilet)');
      }
      setStatus('Profilinfo sikret: ' + done.join(', '), 'ok');
      await refresh();
    } finally { setBusy(false); busy(false); }
  });

  // ------------------------------------------------------------
  //  Finn innlegg
  // ------------------------------------------------------------
  if (api.onBevisProfileProgress) api.onBevisProfileProgress(p => { if (P.scanning && p && p.msg) setStatus(p.msg); });

  el.scan.addEventListener('click', async () => {
    if (state.busy || P.running || P.scanning) return;
    const caseName = caseOk(); if (!caseName) return;
    const st = await api.bevisWindowState();
    if (!st.open) {
      if (!el.url.value.trim()) { setStatus('Åpne profilen først', 'err'); return; }
      await api.bevisOpen({ url: el.url.value.trim(), wait: true, settleMs: 3000 });
    }
    P.scanning = true; setBusy(true); busy(true);
    setStatus('Ruller gjennom profilen …');
    try {
      const r = await api.bevisProfileScan({ maxScreens: +el.max.value || 150, untilDate: el.until.value || '', expand: el.expand.checked });
      if (!r.ok) { setStatus('Fant ikke innlegg: ' + r.error, 'err'); return; }
      if (!r.posts.length) { setStatus('Fant ingen innlegg. Er du logget inn, og står vinduet på profilens innleggsside?', 'err'); return; }
      const saved = await api.bevisProfileSave({ root: state.root, caseName, scan: r, pluginVersion: state.pluginVersion });
      if (!saved.ok) { setStatus('Kunne ikke lagre lista: ' + saved.error, 'err'); return; }
      const why = { maks: 'nådde maks antall skjermer', dato: 'nådde datoen', slutt: 'kom til slutten', stoppet: 'stoppet' }[r.stoppedBy] || r.stoppedBy;
      setStatus('Fant ' + r.posts.length + ' innlegg (' + why + '). Lista er lagret i saken.', 'ok');
      await loadLists(saved.dir, true);
    } finally { P.scanning = false; setBusy(false); busy(false); }
  });
  el.stop.addEventListener('click', () => { api.bevisProfileStop(); setStatus('Stopper …'); });

  // ------------------------------------------------------------
  //  Lister og valg
  // ------------------------------------------------------------
  async function loadLists(selectDir, selectDefault) {
    if (!state.root) return;
    const r = await api.bevisProfileLists({ root: state.root });
    P.lists = r.lists || [];
    const cur = selectDir || (P.current && P.current.dir) || '';
    el.lists.innerHTML = '<option value="">' + (P.lists.length ? 'Tidligere lister …' : 'Ingen lister ennå') + '</option>' + P.lists.map(l =>
      '<option value="' + esc(l.dir) + '"' + (l.dir === cur ? ' selected' : '') + '>' +
      esc(l.case + ' · ' + (l.list.account || l.list.platform) + ' · ' + l.list.scan.posts.length + ' innlegg · ' + l.list.createdAtLocal.split(',')[0]) + '</option>').join('');
    const l = P.lists.find(x => x.dir === cur);
    if (l) select(l, selectDefault);
    else renderList();
  }
  function select(l, selectDefault) {
    P.current = { dir: l.dir, list: l.list, results: l.results || [] };
    P.selected = new Set();
    if (selectDefault) l.list.scan.posts.forEach(p => { if (!p.beforeUntil) P.selected.add(p.index); });
    renderList();
  }
  el.lists.addEventListener('change', () => {
    if (P.running) return;
    const l = P.lists.find(x => x.dir === el.lists.value);
    if (l) select(l, false); else { P.current = null; renderList(); }
  });

  function postStatus(i) {
    const rs = (P.current.results || []).filter(r => r.index === i);
    if (!rs.length) return '';
    if (rs.some(r => r.status === 'ok')) return 'ok';
    return 'err';
  }

  function renderList() {
    const c = P.current;
    el.box.hidden = !c;
    if (!c) { renderRun(); return; }
    const posts = c.list.scan.posts;
    const okN = posts.filter(p => postStatus(p.index) === 'ok').length;
    el.meta.innerHTML = esc(c.list.scan.pageTitle || c.list.scan.pageUrl) + '<br><span class="bv-muted">' +
      esc(posts.length + ' innlegg · ' + c.list.scan.screens + ' skjermer rullet · lista laget ' + c.list.createdAtLocal + ' · ' + okN + ' sikret') + '</span>';
    el.list.innerHTML = posts.map(p => {
      const st = postStatus(p.index);
      return '<li class="bv-plan__row bv-post' + (st ? ' is-' + st : '') + (p.beforeUntil ? ' is-old' : '') + '" data-i="' + p.index + '">' +
        '<input type="checkbox" data-i="' + p.index + '"' + (P.selected.has(p.index) ? ' checked' : '') + (P.running ? ' disabled' : '') + '>' +
        '<span class="bv-plan__n">' + (p.index + 1) + '</span>' +
        '<span class="bv-post__date" title="' + esc(p.dateText) + '">' + esc(p.date ? fmtD(p.date) : (p.dateText || '—').slice(0, 14)) + '</span>' +
        '<span class="bv-plan__d" title="' + esc(p.snippet + '\n' + p.url) + '">' + esc(p.snippet || p.url) + '</span>' +
        '<span class="bv-plan__s">' + (st === 'ok' ? '✓' : st === 'err' ? '✗' : '') + '</span></li>';
    }).join('');
    renderRun();
  }
  function renderRun() {
    const n = P.selected.size;
    el.sel.textContent = P.current ? n + ' valgt' : '';
    el.run.disabled = !P.current || !n || P.running || P.scanning || state.busy && !P.running;
    el.run.textContent = P.running ? 'Sikrer …' : 'Sikre valgte (' + n + ')';
    el.runStop.hidden = !P.running;
  }

  el.list.addEventListener('change', e => {
    const cb = e.target.closest('input[type=checkbox]'); if (!cb) return;
    const i = +cb.dataset.i;
    if (cb.checked) P.selected.add(i); else P.selected.delete(i);
    renderRun();
  });
  el.list.addEventListener('dblclick', e => {
    const row = e.target.closest('.bv-post'); if (!row || !P.current) return;
    const p = P.current.list.scan.posts[+row.dataset.i];
    if (p) api.openExternal(p.url);
  });
  el.all.addEventListener('click', () => { if (!P.current || P.running) return; P.current.list.scan.posts.forEach(p => { if (postStatus(p.index) !== 'ok') P.selected.add(p.index); }); renderList(); });
  el.none.addEventListener('click', () => { if (P.running) return; P.selected.clear(); renderList(); });
  el.reveal.addEventListener('click', () => { if (P.current) api.revealInFinder(P.current.dir + '/liste.csv'); });

  // ------------------------------------------------------------
  //  Sikre valgte
  // ------------------------------------------------------------
  el.run.addEventListener('click', async () => {
    if (P.running || !P.current || !P.selected.size) return;
    if (!caseOk()) return;
    const c = P.current, posts = c.list.scan.posts.filter(p => P.selected.has(p.index));
    P.running = true; P.stop = false;
    setBusy(true); renderList();
    let ok = 0, fail = 0;
    try {
      for (let k = 0; k < posts.length; k++) {
        if (P.stop) break;
        const p = posts[k];
        const row = el.list.querySelector('.bv-post[data-i="' + p.index + '"]');
        if (row) { row.classList.add('is-running'); row.scrollIntoView({ block: 'nearest' }); }
        setStatus('Innlegg ' + (k + 1) + ' av ' + posts.length + ' …');
        const tag = { kind: 'innlegg', listId: c.list.id, index: p.index, total: c.list.scan.posts.length, date: p.date, dateText: p.dateText,
          account: c.list.account || '', profileUrl: c.list.scan.pageUrl, suffix: 'i' + String(p.index + 1).padStart(3, '0') };
        const res = await captureUrl(p.url, tag, 15, el.comments.checked);
        await api.bevisProfileResult({ dir: c.dir, result: Object.assign({ index: p.index, url: p.url }, res) });
        c.results.push(Object.assign({ index: p.index }, res));
        if (res.status === 'ok') { ok++; P.selected.delete(p.index); } else fail++;
        renderList();
        if (res.login) { setStatus('Krever innlogging. Logg inn i vinduet og trykk «Sikre valgte» igjen.', 'err'); P.stop = true; break; }
        if (k % 5 === 4) await refresh();
        if (k < posts.length - 1 && !P.stop && window.bvPace) await window.bvPace(() => P.stop);
      }
    } finally {
      P.running = false;
      setBusy(false);
      renderList();
      await refresh();
      if (!/Krever innlogging/.test(els.status.textContent)) setStatus('Sikret ' + ok + ' innlegg' + (fail ? ', ' + fail + ' feilet (fortsatt valgt — prøv igjen)' : '') + (P.stop ? ' — stoppet' : '') + '.', fail ? 'warn' : 'ok');
      P.stop = false;
    }
  });
  el.runStop.addEventListener('click', () => { P.stop = true; setStatus('Stopper etter dette innlegget …'); });

  // ------------------------------------------------------------
  //  Lagring og visning (kalles fra main.js / stikkprove.js)
  // ------------------------------------------------------------
  window.bvProfileState = () => ({ url: el.url.value, max: el.max.value, until: el.until.value, expand: el.expand.checked, comments: el.comments.checked });
  window.bvProfileApply = s => {
    if (!s) return;
    el.url.value = s.url || '';
    if (s.max) el.max.value = s.max;
    el.until.value = s.until || '';
    if (typeof s.expand === 'boolean') el.expand.checked = s.expand;
    if (typeof s.comments === 'boolean') el.comments.checked = s.comments;
  };
  window.bvProfileShown = () => loadLists();
  window.bvProfileRunning = () => P.running || P.scanning;
  [el.url, el.max, el.until].forEach(x => x.addEventListener('input', scheduleSaveState));
  [el.expand, el.comments].forEach(x => x.addEventListener('change', scheduleSaveState));
})();

shared/dialog.js:
// Faktisk Studio · delt dialog-modul
// window.prompt og window.confirm er blokkert i Electron. Vi bygger
// en custom modal som matcher Faktisk-designet og returnerer Promise.

(function () {
  function ensureContainer() {
    let host = document.getElementById('faktisk-dialog-host');
    if (host) return host;
    host = document.createElement('div');
    host.id = 'faktisk-dialog-host';
    document.body.appendChild(host);
    const style = document.createElement('style');
    style.textContent = `
      #faktisk-dialog-host {
        position: fixed; inset: 0; display: none;
        align-items: center; justify-content: center;
        background: rgba(0,0,0,0.45);
        z-index: 99999;
        font-family: var(--font-regular), "Helvetica Neue", sans-serif;
      }
      #faktisk-dialog-host.open { display: flex; }
      .fd-card {
        background: #fff;
        color: #212121;
        border-radius: 14px;
        padding: 24px 28px;
        width: 420px;
        max-width: calc(100vw - 40px);
        box-shadow: 0 24px 60px rgba(0,0,0,0.4);
        display: flex;
        flex-direction: column;
        gap: 14px;
      }
      .fd-message {
        font-size: 15px;
        line-height: 1.4;
        margin: 0;
        color: #212121;
        font-weight: 500;
      }
      .fd-input {
        background: #f0f0f0;
        border: 0;
        outline: 0;
        border-radius: 7px;
        padding: 10px 12px;
        font-size: 14px;
        font-family: inherit;
        color: #212121;
        font-weight: 500;
      }
      .fd-input:focus { outline: 2px solid #0050FC; }
      .fd-row {
        display: flex;
        gap: 10px;
        justify-content: flex-end;
        margin-top: 4px;
      }
      .fd-btn {
        padding: 10px 20px;
        font-size: 14px;
        font-weight: bold;
        border: 0;
        border-radius: 9px;
        cursor: pointer;
        font-family: inherit;
      }
      .fd-btn-primary { background: #0050FC; color: #fff; }
      .fd-btn-primary:hover { background: #0040D9; }
      .fd-btn-cancel { background: #e0e0e0; color: #212121; }
      .fd-btn-cancel:hover { background: #d0d0d0; }
      .fd-btn-danger { background: #d04040; color: #fff; }
      .fd-btn-danger:hover { background: #e85050; }
      .fd-progress-label {
        font-size: 13px;
        color: #555;
        margin: 0;
      }
      .fd-progress {
        height: 8px;
        background: #e0e0e0;
        border-radius: 4px;
        overflow: hidden;
      }
      .fd-progress__bar {
        height: 100%;
        background: #0050FC;
        transition: width 0.2s;
      }
      .project-card {
        background: #0050FC;
        color: #fff;
        border-radius: 9px;
        padding: 12px 16px;
        cursor: pointer;
        display: flex;
        flex-direction: column;
        gap: 4px;
        position: relative;
        transition: background 0.15s;
      }
      .project-card:hover { background: #0040D9; }
      .project-card__name { font-weight: bold; font-size: 14px; }
      .project-card__meta { font-size: 11px; opacity: 0.85; }
      .project-card__delete {
        position: absolute; top: 6px; right: 8px;
        background: rgba(255,255,255,0.18); color: #fff;
        width: 22px; height: 22px; border-radius: 4px;
        display: none; align-items: center; justify-content: center;
        font-size: 14px; cursor: pointer; border: 0;
      }
      .project-card:hover .project-card__delete { display: flex; }
      .project-card__delete:hover { background: rgba(255,80,80,0.85); }
    `;
    document.head.appendChild(style);
    return host;
  }

  function open(html, onMount) {
    const host = ensureContainer();
    host.innerHTML = `<div class="fd-card">${html}</div>`;
    host.classList.add('open');
    if (onMount) onMount(host);
    return () => { host.classList.remove('open'); host.innerHTML = ''; };
  }

  function prompt(message, defaultValue) {
    return new Promise(resolve => {
      const close = open(`
        <p class="fd-message"></p>
        <input class="fd-input" type="text">
        <div class="fd-row">
          <button class="fd-btn fd-btn-cancel" data-act="cancel">Avbryt</button>
          <button class="fd-btn fd-btn-primary" data-act="ok">OK</button>
        </div>
      `, host => {
        host.querySelector('.fd-message').textContent = message || '';
        const input = host.querySelector('.fd-input');
        input.value = defaultValue || '';
        setTimeout(() => { input.focus(); input.select(); }, 30);
        const cleanup = result => { close(); resolve(result); };
        host.querySelector('[data-act="ok"]').onclick = () => cleanup(input.value);
        host.querySelector('[data-act="cancel"]').onclick = () => cleanup(null);
        input.onkeydown = e => {
          if (e.key === 'Enter') cleanup(input.value);
          if (e.key === 'Escape') cleanup(null);
        };
      });
    });
  }

  function confirm(message, danger) {
    return new Promise(resolve => {
      const okClass = danger ? 'fd-btn-danger' : 'fd-btn-primary';
      const close = open(`
        <p class="fd-message"></p>
        <div class="fd-row">
          <button class="fd-btn fd-btn-cancel" data-act="cancel">Avbryt</button>
          <button class="fd-btn ${okClass}" data-act="ok">${danger ? 'Slett' : 'OK'}</button>
        </div>
      `, host => {
        host.querySelector('.fd-message').textContent = message || '';
        const cleanup = result => { close(); resolve(result); };
        host.querySelector('[data-act="ok"]').onclick = () => cleanup(true);
        host.querySelector('[data-act="cancel"]').onclick = () => cleanup(false);
        document.onkeydown = e => {
          if (e.key === 'Escape') { document.onkeydown = null; cleanup(false); }
        };
      });
    });
  }

  function alert(message) {
    return new Promise(resolve => {
      const close = open(`
        <p class="fd-message"></p>
        <div class="fd-row">
          <button class="fd-btn fd-btn-primary" data-act="ok">OK</button>
        </div>
      `, host => {
        host.querySelector('.fd-message').textContent = message || '';
        const cleanup = () => { close(); resolve(); };
        host.querySelector('[data-act="ok"]').onclick = cleanup;
      });
    });
  }

  window.faktiskDialog = { prompt, confirm, alert };
})();

shared/embed-tokens.js:
// Faktisk embed-tokens — sentral kilde for alle plugins.
//
// Dette er den KANONISKE kopien. Ved bygging av bundle.json kopieres denne
// filen inn i hver plugin/<id>/shared/embed-tokens.js. Alle plugins bruker
// window.FaktiskEmbedBase.* i sin buildEmbedSnippet.
//
// Tokens matcher faktisk.no sin typografi:
// - Unica77 er UI/caption/factbox-fonten
// - #0050FC er Faktisk brand-blå
// - Font-vektene 300/500 er de Labrador-siden faktisk laster
//
// Endringer her får effekt i alle embeds ved neste build+release.
// I fremtidig native-migrering vil Labrador-temaet definere de samme
// --fk-*-variablene på artikkel-nivå, og embeds arver dem gratis.

(function (root) {
  'use strict';

  const TOKENS = {
    // Typografi
    font:         '"Unica77", "Helvetica Neue", Helvetica, Arial, sans-serif',
    fwNormal:     300,   // Unica77 Light
    fwBold:       500,   // Unica77 Medium
    lineHeight:   1.4,

    // Farger
    ink:          '#212121',   // hovedtekst
    inkDim:       '#5A5A5A',   // sekundærtekst
    white:        '#FFFFFF',
    blue:         '#0050FC',   // Faktisk brand-blå
    surface:      '#D9D9D9',   // container-bakgrunn (lys grå)
    surfaceDark:  '#C3C3C3',   // mørkere container (feks bildeanalyse par-container)

    // Geometri
    radiusSm:     '4px',
    radiusMd:     '8px',
    radiusLg:     '16px',

    // Skygger
    shadowSm:     '0 2px 8px rgba(0,0,0,0.10)',
    shadowMd:     '0 4px 16px rgba(0,0,0,0.15)',
    shadowLg:     '0 10px 30px rgba(0,0,0,0.45), 0 2px 6px rgba(0,0,0,0.3)',

    // Spacing (unicorn-scale)
    spaceXs:      '4px',
    spaceSm:      '8px',
    spaceMd:      '16px',
    spaceLg:      '24px',
    spaceXl:      '32px',
  };

  /**
   * Genererer CSS-variabel-blokka som skal ligge på embed-roten.
   * Kall denne først i buildEmbedSnippet slik at plugin-spesifikk CSS
   * kan bruke `var(--fk-blue)`, `var(--fk-font)` osv.
   *
   * @param {string} scope - Klassen som identifiserer denne embed-instansen
   *                        (feks 'ffes-abc123' eller 'banl-xyz789')
   * @returns {string} CSS-tekst
   */
  function getBaseCss(scope) {
    return `
    .${scope} {
      --fk-font: ${TOKENS.font};
      --fk-fw-normal: ${TOKENS.fwNormal};
      --fk-fw-bold: ${TOKENS.fwBold};
      --fk-line-height: ${TOKENS.lineHeight};
      --fk-ink: ${TOKENS.ink};
      --fk-ink-dim: ${TOKENS.inkDim};
      --fk-white: ${TOKENS.white};
      --fk-blue: ${TOKENS.blue};
      --fk-surface: ${TOKENS.surface};
      --fk-surface-dark: ${TOKENS.surfaceDark};
      --fk-radius-sm: ${TOKENS.radiusSm};
      --fk-radius-md: ${TOKENS.radiusMd};
      --fk-radius-lg: ${TOKENS.radiusLg};
      --fk-shadow-sm: ${TOKENS.shadowSm};
      --fk-shadow-md: ${TOKENS.shadowMd};
      --fk-shadow-lg: ${TOKENS.shadowLg};
      --fk-space-xs: ${TOKENS.spaceXs};
      --fk-space-sm: ${TOKENS.spaceSm};
      --fk-space-md: ${TOKENS.spaceMd};
      --fk-space-lg: ${TOKENS.spaceLg};
      --fk-space-xl: ${TOKENS.spaceXl};

      font-family: var(--fk-font);
      font-weight: var(--fk-fw-normal);
      line-height: var(--fk-line-height);
      color: var(--fk-ink);
    }`;
  }


  /**
   * Beskytter en embed mot stilarket på siden den limes inn i (faktisk.no / Labrador).
   * Opt-in: kall på hele CSS-teksten til embedden før den legges i <style>.
   *  - roten (.scope) nullstilles med all:initial og får Faktisk-font/farge/linjehøyde
   *  - alle etterkommere nullstilles (margin, padding, border, font, listetegn …)
   *  - alle regler prefikses med dobbel rotklasse (.scope.scope …) så de veier tyngre enn sidens regler
   *  - font-weight bold/600/700 → 500 og normal/400 → 300 (faktisk.no laster bare Unica77 300 og 500)
   * Sidens regler med !important kan ingen embed overstyre.
   *
   * @param {string} css   - embeddens CSS
   * @param {string} scope - klassen på embeddens rot-element (uten punktum)
   * @returns {string} beskyttet CSS
   */
  function isolate(css, scope) {
    const R = '.' + scope, RR = R + R;
    css = String(css || '')
      .replace(/font-weight:\s*(bold|700|600|bolder)\b/g, 'font-weight: ' + TOKENS.fwBold)
      .replace(/font-weight:\s*(normal|400)\b/g, 'font-weight: ' + TOKENS.fwNormal);
    function fixSel(sel) {
      return sel.split(',').map(s => s.trim()).filter(Boolean).map(s => {
        if (s.startsWith(R) && !/[\w-]/.test(s.charAt(R.length) || ' ')) return RR + s.slice(R.length);
        return RR + ' ' + s;
      }).join(',');
    }
    function walk(src) {
      let out = '', i = 0;
      while (i < src.length) {
        const j = src.indexOf('{', i);
        if (j < 0) { out += src.slice(i); break; }
        const head = src.slice(i, j), hs = head.trim();
        if (hs.charAt(0) === '@') {
          let depth = 1, k = j + 1;
          while (k < src.length && depth) { if (src[k] === '{') depth++; else if (src[k] === '}') depth--; k++; }
          const inner = src.slice(j + 1, k - 1);
          out += head + '{' + (/^@(media|container|supports)/.test(hs) ? walk(inner) : inner) + '}';
          i = k; continue;
        }
        const k = src.indexOf('}', j);
        out += head.slice(0, head.length - head.trimStart().length) + fixSel(hs) + src.slice(j, k + 1);
        i = k + 1;
      }
      return out;
    }
    const reset = `
    ${RR} { all: initial; display: block; box-sizing: border-box; font-family: ${TOKENS.font}; font-weight: ${TOKENS.fwNormal};
      line-height: ${TOKENS.lineHeight}; color: ${TOKENS.ink}; text-align: left; -webkit-font-smoothing: antialiased; }
    ${RR} *, ${RR} *::before, ${RR} *::after { box-sizing: border-box; margin: 0; padding: 0; border: 0; background: none;
      font: inherit; line-height: inherit; color: inherit; letter-spacing: normal; text-transform: none; text-indent: 0;
      text-decoration: none; text-align: inherit; list-style: none; float: none; max-width: none; min-width: 0;
      min-height: 0; box-shadow: none; outline: 0; quotes: none; vertical-align: baseline; }
    ${RR} img, ${RR} svg, ${RR} canvas, ${RR} video { display: block; max-width: none; height: auto; }
`;
    return reset + walk(css);
  }

  root.FaktiskEmbedBase = { TOKENS, getBaseCss, isolate };
})(typeof window !== 'undefined' ? window : globalThis);

shared/fk-import.js:
// Faktisk Studio · felles filimport (CSV, TSV, TXT og Excel .xlsx) — kanonisk kopi i plugins/_shared/.
//
//   FaktiskImport.readFile(file)            → Promise<{ sheets: [{ name, rows: string[][] }] }>
//   FaktiskImport.openDialog({ title, fields, onApply })
//        fields:  [{ key, label, guess: /regex for kolonneoverskrift/, required }]
//        onApply: (objekter[]) — én per datarad, med feltene som nøkler
//
// Ingen eksterne bibliotek: .xlsx pakkes ut med nettleserens DecompressionStream og leses med DOMParser.
// CSV: finner skilletegn selv (semikolon, komma, tabulator), støtter "sitert, tekst", og faller tilbake til
// Windows-1252 når fila ikke er gyldig UTF-8 (vanlig for CSV lagret fra norsk Excel).
(function (root) {
  'use strict';

  // ---------- CSV / TSV ----------
  function decodeText(buf) {
    var u = new Uint8Array(buf), s;
    try { s = new TextDecoder('utf-8', { fatal: true }).decode(u); }
    catch (e) { s = new TextDecoder('windows-1252').decode(u); }
    return s.replace(/^﻿/, '');
  }
  function sniffDelim(text) {
    var line = text.split(/\r?\n/).find(function (l) { return l.trim(); }) || '';
    var best = '\t', n = -1;
    ['\t', ';', ','].forEach(function (d) {
      var c = 0, q = false;
      for (var i = 0; i < line.length; i++) { var ch = line[i]; if (ch === '"') q = !q; else if (!q && ch === d) c++; }
      if (c > n) { n = c; best = d; }
    });
    return best;
  }
  function parseDelimited(text, d) {
    d = d || sniffDelim(text);
    var rows = [], row = [], cell = '', q = false;
    for (var i = 0; i < text.length; i++) {
      var ch = text[i];
      if (q) {
        if (ch === '"') { if (text[i + 1] === '"') { cell += '"'; i++; } else q = false; }
        else cell += ch;
      } else if (ch === '"' && cell === '') q = true;
      else if (ch === d) { row.push(cell); cell = ''; }
      else if (ch === '\n' || ch === '\r') {
        if (ch === '\r' && text[i + 1] === '\n') i++;
        row.push(cell); rows.push(row); row = []; cell = '';
      } else cell += ch;
    }
    if (cell !== '' || row.length) { row.push(cell); rows.push(row); }
    return clean(rows);
  }
  function clean(rows) {
    rows = rows.map(function (r) { return r.map(function (c) { return String(c == null ? '' : c).trim(); }); })
      .filter(function (r) { return r.some(function (c) { return c !== ''; }); });
    var w = rows.reduce(function (m, r) { return Math.max(m, r.length); }, 0);
    // fjern tomme kolonner helt til høyre
    while (w > 0 && rows.every(function (r) { return !r[w - 1]; })) w--;
    return rows.map(function (r) { var o = r.slice(0, w); while (o.length < w) o.push(''); return o; });
  }

  // ---------- XLSX (zip + XML) ----------
  function unzip(buf) {
    var dv = new DataView(buf), u = new Uint8Array(buf), eocd = -1;
    for (var i = u.length - 22; i >= Math.max(0, u.length - 66000); i--) if (dv.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
    if (eocd < 0) throw new Error('Fila ser ikke ut som en gyldig .xlsx (fant ikke zip-katalog).');
    var n = dv.getUint16(eocd + 10, true), off = dv.getUint32(eocd + 16, true), files = {};
    for (var k = 0; k < n; k++) {
      if (dv.getUint32(off, true) !== 0x02014b50) break;
      var method = dv.getUint16(off + 10, true), csize = dv.getUint32(off + 20, true);
      var nlen = dv.getUint16(off + 28, true), xlen = dv.getUint16(off + 30, true), clen = dv.getUint16(off + 32, true);
      var lho = dv.getUint32(off + 42, true), name = new TextDecoder().decode(u.subarray(off + 46, off + 46 + nlen));
      var dstart = lho + 30 + dv.getUint16(lho + 26, true) + dv.getUint16(lho + 28, true);
